const raw = $json.body?.body || $json.body || $json;

const resumeText = raw.resumeText || raw.resume_text || '';
const resumeLower = resumeText.toLowerCase();

// 1. Extracción de Educación
let educacion = raw.education || [];
if (!educacion.length) {
  let nivel = 'Licenciatura / Ingeniería';
  if (/maestria|master|posgrado/.test(resumeLower)) nivel = 'Maestría / Posgrado';
  else if (/tecnico|carrera tecnica|diplomado/.test(resumeLower)) nivel = 'Técnico Especializado';
  educacion = [{ grado: nivel, estado: 'Completado' }];
}

// 2. Extracción de Últimos 3 Empleos y Permanencia
let ultimos3 = raw.last_3_jobs || [];
let avgTenure = raw.avg_tenure || 2.5;

let fitScoreBase = raw.fitScore || raw.fit_score || 75;
let stabilityScore = avgTenure >= 3.0 ? 95 : (avgTenure >= 2.0 ? 85 : 70);
let compositeFitScore = Math.round((fitScoreBase * 0.70) + (stabilityScore * 0.30));

return {
  json: {
    id: raw.id || 'cand_' + Date.now(),
    name: raw.name || '',
    email: raw.email || '',
    phone: raw.phone || '',
    resume_text: resumeText,
    stage: raw.stage || 'Filtrado',
    competencies: JSON.stringify({
      tech_skills: raw.competencies || {},
      last_3_jobs: ultimos3,
      education: educacion,
      stability_score: stabilityScore,
      avg_tenure_years: avgTenure
    }),
    fit_score: compositeFitScore,
    summary: raw.summary || ('Candidato con formación ' + (educacion[0]?.grado || 'Profesional') + ' y permanencia promedio de ' + avgTenure + ' años en últimos empleos.'),
    strengths: raw.strengths || [],
    growths: raw.growths || [],
    recommended_questions: raw.recommendedQuestions || raw.recommended_questions || [],
    suggested_time: raw.suggestedTime || raw.suggested_time || null,
    channel: raw.channel || 'Postulación Web',
    vacancy_id: raw.vacancyId || raw.vacancy_id || null,
    double_check_report: raw.doubleCheckReport || raw.double_check_report || null,
    interview_speech: raw.interviewSpeech || raw.interview_speech || null,
    comments: raw.comments || ''
  }
};

const raw = $json.body?.body || $json.body || $json;
return {
  json: {
    id: raw.id || 'vac_' + Date.now(),
    title: raw.title || '',
    department: raw.department || 'Consultoría',
    location: raw.location || 'CDMX / Remoto',
    description: raw.description || '',
    requirements: raw.requirements || [],
    experience_years: raw.experienceYears || raw.experience_years || 3,
    salary_range: raw.salaryRange || raw.salary_range || 'A convenir',
    status: raw.status || 'Activa',
    min_competencies: JSON.stringify(raw.minCompetenciesRequired || raw.min_competencies || {}),
    english_level: raw.englishLevel || raw.english_level || 'Medio',
    modalidad: raw.modalidad || 'Híbrido'
  }
};

const raw = $json.body?.body || $json.body || $json;
const meetingLink = raw.meetingLink || raw.meeting_link || 'https://meet.google.com/eas-recruiting';
const candidateName = raw.candidateName || raw.candidate_name || 'Candidato';
const date = raw.date || new Date().toISOString();
